-- Corrections du quiz de fin de semaine : marees.
--
-- Générées par scripts/importer-quiz.mjs. `data` porte la version adulte, 
-- `data.version_enfant` la version enfant du même sujet. Remplace `version_moniteur`
-- (même rôle, jamais exploité par un vrai choix au lancement avant ce jour).

UPDATE game_cards SET related_objective_id = '1', data = '{"question":"Pourquoi y a-t-il deux marées hautes et deux marées basses chaque jour ?","answers":["La Lune attire l''eau deux fois par jour","La Terre traverse deux fois par jour les deux renflements d''eau créés par la Lune","Le Soleil et la Lune alternent leur influence","C''est dû aux courants marins uniquement"],"correctAnswerIndex":1,"explanation":"La Lune crée deux renflements d''eau, un de chaque côté de la Terre. En tournant sur elle-même, la Terre fait passer chaque côte dans ces deux renflements au cours d''une journée : d''où deux marées hautes.","version_enfant":{"question":"En une journée, combien de fois la mer monte-t-elle complètement ?","answers":["1 fois","2 fois","5 fois","Ça change tous les jours"],"correctAnswerIndex":1,"explanation":"La mer monte 2 fois et descend 2 fois par jour. Entre deux marées hautes, il se passe un peu plus de 12 heures."}}'::jsonb WHERE id = '8765bf8c-9b31-4d7c-9f40-4126bfda7244';
UPDATE game_cards SET related_objective_id = '1', data = '{"question":"Qu''est-ce qui fait monter et descendre la mer ?","answers":["L''attraction de la Lune, et un peu celle du Soleil","Le vent qui souffle sur l''océan","Le passage des bateaux","Le réchauffement de l''eau par le soleil"],"correctAnswerIndex":0,"explanation":"La Lune attire l''eau et crée deux renflements. Le Soleil joue le même rôle, mais deux fois plus faiblement car il est bien plus loin.","version_enfant":{"question":"La mer monte et descend tous les jours. Qu''est-ce qui la fait bouger comme ça ?","answers":["La Lune, qui tire sur l''eau","Le vent qui souffle sur la mer","Les bateaux qui passent","L''eau qui chauffe au soleil"],"correctAnswerIndex":0,"explanation":"C''est la Lune qui tire sur l''eau de la mer, comme un aimant. Le Soleil aide un peu aussi, mais il est beaucoup plus loin."}}'::jsonb WHERE id = '9adf3e06-274c-4984-818d-74532a480c23';
UPDATE game_cards SET related_objective_id = '2', data = '{"question":"Comment connaît-on à l''avance les horaires de marée ?","answers":["En observant la couleur de l''eau","Grâce aux annuaires du SHOM, calculés des années à l''avance","En interrogeant les pêcheurs locaux","Il n''existe pas de méthode fiable"],"correctAnswerIndex":1,"explanation":"Le SHOM (Service Hydrographique et Océanographique de la Marine) publie des annuaires officiels donnant les horaires de marée pour tous les ports français, des années à l''avance.","version_enfant":{"question":"Comment fait-on pour savoir à quelle heure la mer sera haute demain ?","answers":["On regarde la couleur de l''eau","On regarde un calendrier des marées ou une appli","On attend de voir","On demande aux pêcheurs, personne d''autre ne sait"],"correctAnswerIndex":1,"explanation":"Les marées sont tellement régulières qu''on peut les calculer des années à l''avance. Il suffit de lire le calendrier des marées."}}'::jsonb WHERE id = '20a13cd3-e93a-480e-8688-6d9145ed3ba2';
UPDATE game_cards SET related_objective_id = '3', data = '{"question":"Pourquoi l''heure de la marée n''est-elle pas la même partout en France ?","answers":["La marée est une onde qui se propage et contourne caps et baies","L''eau est plus salée à certains endroits","Il fait plus chaud dans le Sud","Les horloges locales diffèrent"],"correctAnswerIndex":0,"explanation":"La marée n''est pas un niveau qui monte partout en même temps : c''est une onde qui doit contourner les caps et remonter les baies, ce qui retarde ou accélère son passage.","version_enfant":{"question":"Pourquoi la mer n''est-elle pas haute à la même heure partout en France ?","answers":["Parce que la forme des côtes ralentit ou accélère l''eau","Parce que l''eau est plus salée à certains endroits","Parce qu''il fait plus chaud dans le Sud","Parce que les horloges sont différentes"],"correctAnswerIndex":0,"explanation":"L''eau doit contourner les caps, entrer dans les baies… Comme dans un couloir plein d''obstacles, elle n''arrive pas partout en même temps."}}'::jsonb WHERE id = 'f58bd36f-eaa4-4af2-b298-2f909a200a9f';
UPDATE game_cards SET related_objective_id = '4', data = '{"question":"Comment s''appelle la zone couverte à marée haute et découverte à marée basse ?","answers":["L''estran","La dune","Le port","La falaise"],"correctAnswerIndex":0,"explanation":"L''estran est soumis à des conditions extrêmes — immergé puis à l''air libre — ce qui en fait un milieu riche en espèces hyper-spécialisées.","version_enfant":{"question":"Cette partie de la plage est couverte par la mer à marée haute, et à l''air libre à marée basse. Comment on l''appelle ?","answers":["L''estran","La dune","Le port","La falaise"],"correctAnswerIndex":0,"explanation":"L''estran, c''est la bande de plage qui se découvre à marée basse. C''est là qu''on trouve les coquillages, les crabes et les petites mares."}}'::jsonb WHERE id = '09edcd82-aa20-430b-bbcb-2964abf413ac';
UPDATE game_cards SET related_objective_id = '8', data = '{"question":"La marée monte-t-elle à vitesse constante pendant le flot ?","answers":["Oui, la vitesse est régulière","Non, elle est lente au début et à la fin, rapide au milieu (règle des douzièmes)","Non, elle ralentit progressivement du début à la fin","Non, elle est irrégulière et imprévisible"],"correctAnswerIndex":1,"explanation":"La règle des douzièmes découpe le flot en 1/12, 2/12, 3/12, 3/12, 2/12, 1/12 du marnage total, heure par heure : c''est entre la 2e et la 4e heure que l''eau monte le plus vite.","version_enfant":{"question":"La marée monte-t-elle à la même vitesse tout au long de la matinée ?","answers":["Oui, toujours pareil","Non, elle monte lentement au début, très vite au milieu, puis lentement à la fin","Non, elle monte de plus en plus vite jusqu''à la fin","Non, elle ralentit tout du long"],"correctAnswerIndex":1,"explanation":"La mer monte lentement au début, très vite au milieu, puis lentement à la fin. C''est au milieu qu''on se fait le plus facilement surprendre."}}'::jsonb WHERE id = '6914fa20-7e8b-49b2-9999-61bf2161db1a';
UPDATE game_cards SET related_objective_id = '9', data = '{"question":"À quel moment de la marée les courants sont-ils les plus forts ?","answers":["Au début du flot","À l''étale","À mi-marée","À la marée haute"],"correctAnswerIndex":2,"explanation":"C''est pendant les heures où la marée monte ou descend le plus vite (mi-marée) que le débit d''eau est maximal, donc que les courants sont les plus forts. À l''étale, le courant tombe presque à zéro.","version_enfant":{"question":"À quel moment le courant tire-t-il le plus fort ?","answers":["Juste au début, quand l''eau commence à monter","Pile au milieu, quand la mer monte le plus vite","Quand la mer est tout en haut","Le courant est toujours pareil"],"correctAnswerIndex":1,"explanation":"C''est au milieu de la marée que l''eau se déplace le plus vite, donc que le courant tire le plus fort. C''est le moment où il faut être le plus attentif."}}'::jsonb WHERE id = '0a764548-b0e1-4a26-b2e0-3b37a2b870ca';
UPDATE game_cards SET related_objective_id = '10', data = '{"question":"Comment appelle-t-on la marée montante, en vocabulaire marin ?","answers":["Le jusant","L''étale","Le flot","La vive-eau"],"correctAnswerIndex":2,"explanation":"Le flot désigne la marée montante, le jusant la descendante. Entre les deux se glisse l''étale, le bref moment où le courant s''arrête avant de repartir.","version_enfant":{"question":"Comment les marins appellent-ils la mer qui monte ?","answers":["Le jusant","L''étale","Le flot","La vive-eau"],"correctAnswerIndex":2,"explanation":"Le flot, c''est la mer qui monte. Le jusant, c''est la mer qui descend. L''étale, c''est la pause entre les deux."}}'::jsonb WHERE id = '9fda2754-2b16-4619-8351-fb96a51ea82d';
UPDATE game_cards SET related_objective_id = '10', data = '{"question":"Qu''est-ce que l''étale de marée ?","answers":["La période où le courant est le plus fort","Le moment de transition où le courant est quasi nul","La hauteur maximale atteinte par la marée","La durée totale d''une marée"],"correctAnswerIndex":1,"explanation":"L''étale est un bref moment de pause entre le flot et le jusant, où le courant est quasi nul.","version_enfant":{"question":"Comment s''appelle le moment où l''eau ne monte plus et ne descend pas encore ?","answers":["Le flot","L''étale","Le jusant","La vive-eau"],"correctAnswerIndex":1,"explanation":"L''étale, c''est la petite pause entre la mer qui monte et la mer qui descend. Le courant s''arrête presque complètement."}}'::jsonb WHERE id = 'e2b8c280-5cb9-4024-a93c-65655f5e0f4c';
UPDATE game_cards SET related_objective_id = '13', data = '{"question":"Comment repérer que la mer monte ou descend, sans montre ni application ?","answers":["En goûtant l''eau, plus salée quand elle monte","En comparant le niveau de l''eau à un point fixe, à quelques minutes d''intervalle","En comptant les vagues","En observant la direction du vent"],"correctAnswerIndex":1,"explanation":"À l''œil nu, la marée est trop lente pour se voir en direct. Il faut comparer le niveau de l''eau à un repère fixe (rocher, poteau) à quelques minutes d''intervalle.","version_enfant":{"question":"Comment savoir si la mer monte, sans montre ni téléphone ?","answers":["En goûtant l''eau","En choisissant un rocher ou un poteau et en regardant si l''eau monte dessus","En comptant les vagues","En regardant le vent"],"correctAnswerIndex":1,"explanation":"On ne voit pas la mer monter en direct. Il faut un repère fixe et un peu de patience : cinq minutes plus tard, l''eau aura bougé sur le repère."}}'::jsonb WHERE id = '81f08493-5de6-477e-bea1-358de8f9d899';
UPDATE game_cards SET related_objective_id = '14', data = '{"question":"Quel est le meilleur indice naturel pour savoir jusqu''où va monter la mer ?","answers":["La hauteur des nuages","La laisse de haute mer : la ligne de débris laissée par la dernière marée haute","La couleur de l''eau au large","La hauteur des vagues actuelles"],"correctAnswerIndex":1,"explanation":"La laisse de haute mer marque le niveau atteint par la dernière marée haute. Si des affaires sont posées en dessous, elles risquent d''être emportées.","version_enfant":{"question":"Comment sait-on jusqu''où la mer va monter aujourd''hui ?","answers":["En regardant les nuages","En repérant la ligne d''algues laissée par la mer précédente","En regardant la couleur de l''eau","En comptant les vagues"],"correctAnswerIndex":1,"explanation":"La ligne d''algues montre jusqu''où la mer est déjà montée. On pose ses affaires bien au-dessus."}}'::jsonb WHERE id = '3a52ae12-a38f-4871-b57b-056e7a43a656';
UPDATE game_cards SET related_objective_id = '106', data = '{"question":"Que signifie un fort coefficient de marée (vive-eau) ?","answers":["La marée montante est plus rapide que la descente","L''estran découvre plus loin et les courants sont plus forts","La mer est plus calme et sans courant","Il y a moins d''organismes sur l''estran"],"correctAnswerIndex":1,"explanation":"Un fort coefficient signifie une grande amplitude : l''estran découvre plus loin, les courants sont plus puissants.","version_enfant":{"question":"Un grand coefficient de marée, ça veut dire quoi ?","answers":["La mer monte plus vite que d''habitude","L''eau va plus loin et le courant tire plus fort","La mer est plus calme","Il y a moins d''animaux sur la plage"],"correctAnswerIndex":1,"explanation":"Avec un grand coefficient, l''eau découvre beaucoup plus loin et le courant est plus fort. On regarde ce chiffre avant de partir."}}'::jsonb WHERE id = '960d40e4-eab3-4ca8-aec6-bf9c1962e561';
UPDATE game_cards SET related_objective_id = '106', data = '{"question":"Pourquoi vérifier le coefficient de marée avant une sortie ?","answers":["Pour choisir la couleur de sa combinaison","Pour évaluer la sécurité : plus le coefficient est fort, plus les courants sont puissants","Pour savoir si la mer sera chaude","Pour connaître la direction du vent dominant"],"correctAnswerIndex":1,"explanation":"Un fort coefficient signifie plus de courant et un estran qui découvre plus loin — cela change la durée disponible et la force des courants.","version_enfant":{"question":"Avant de partir, pourquoi regarder le coefficient de la marée ?","answers":["Pour choisir la couleur de sa combinaison","Parce qu''un grand coefficient veut dire plus de courant","Pour savoir si l''eau sera chaude","Pour connaître la direction du vent"],"correctAnswerIndex":1,"explanation":"Plus le coefficient est grand, plus le courant tire fort et plus l''eau découvre loin. C''est important pour la sécurité."}}'::jsonb WHERE id = 'bbedb830-5aca-47ae-88c3-3598404ea698';
UPDATE game_cards SET related_objective_id = '91', data = '{"question":"Pourquoi les horaires de marée se décalent-ils d''environ 50 minutes chaque jour ?","answers":["Le vent dominant ralentit la marée","Le jour lunaire dure 24h50 : la Lune avance sur son orbite pendant que la Terre tourne","La rotation de la Terre s''accélère légèrement","La salinité de l''eau change chaque jour"],"correctAnswerIndex":1,"explanation":"La Lune avance dans son orbite pendant que la Terre tourne sur elle-même. Le jour lunaire dure environ 24h50, donc chaque marée arrive environ 50 minutes plus tard que la veille.","version_enfant":{"question":"Pourquoi l''heure de la marée change chaque jour ?","answers":["À cause du vent","Parce que la Lune met un peu plus d''un jour à revenir au même endroit au-dessus de nous","Parce que la Terre tourne plus vite certains jours","Parce que l''eau est plus ou moins salée"],"correctAnswerIndex":1,"explanation":"La Lune met 24h50 à repasser au-dessus de nous. La marée la suit : environ 50 minutes de retard chaque jour."}}'::jsonb WHERE id = 'c520e049-3611-4ce3-8624-66c68ab9b111';
UPDATE game_cards SET related_objective_id = '11', data = '{"question":"Pourquoi les marées rythment-elles la vie sur l''estran et les activités humaines ?","answers":["Elles modifient uniquement la température de l''eau","Chaque espèce s''est adaptée à l''alternance immersion/émersion, et les activités humaines suivent le même rythme","Elles créent un vent qui affecte les oiseaux","Elles changent la couleur de l''eau selon le coefficient"],"correctAnswerIndex":1,"explanation":"Certaines espèces se nourrissent à marée basse, d''autres se reproduisent à marée haute. Pêche, accès aux ports, sorties en mer suivent le même rythme.","version_enfant":{"question":"Pourquoi dit-on que tout le monde vit au rythme de la marée ici ?","answers":["Parce que ça change la couleur de l''eau","Parce que les animaux et les gens s''organisent selon la mer haute ou basse","Parce que ça fait du vent","Ce n''est pas vrai, la marée ne concerne que les bateaux"],"correctAnswerIndex":1,"explanation":"Les oiseaux qui fouillent à marée basse, les pêcheurs à pied, les bateaux qui sortent : tout suit le même rythme, celui de la marée."}}'::jsonb WHERE id = '16c1a857-4ab3-4419-9516-3e34b3cc9e58';
